"""Read-only proof of LP's active time challenge and dormant survival branch."""
import json,hashlib
from pathlib import Path
from importlib import import_module
n=import_module('native-code').NativeCode();root=Path(__file__).resolve().parent.parent
files=[]
for name,lo,hi,minimum in [('entry',0x613c20,0x6178d7,0x6176f0),('clock',0x5c7a60,0x5c8470,0x5c840f),('result',0x5d99d0,0x5da230,0x5d99d0),('format',0x5da230,0x5da360,0x5da230),('enemy-release',0x5c8470,0x5c9971,0x5c9313),('death',0x618ce0,0x61b44d,0x61b3e0),('cancel',0x5e6c20,0x5e7620,0x5e7578),('record-save',0x5ad0b0,0x5ad238,0x5ad1eb),('record-ui',0x578e80,0x57a4b0,0x57a30e)]:
 rows=[r for r in n.disasm(lo,hi) if r[0]>=minimum];path=root/'reports'/('native-challenge-'+name+'.txt');path.write_text('\n'.join(f'{a:08x} {m:8s} {o}' for a,m,o in rows),encoding='utf8');files.append({'file':'reports/'+path.name,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
assert n.string(0x417da4)=='#生存挑战' and n.string(0x417dd8)=='#时间挑战'
assert n.string(0x417db4)=='#move C30 49 53' and n.string(0x417de8)=='#move E30 15 25'
r=n.disasm(0x5c7a60,0x5c8470);assert any(a==0x5c8419 and m=='inc' and o=='dword ptr [0x63ede4]' for a,m,o in r)
r=n.disasm(0x5d99d0,0x5da230)
assert any(a==0x5da034 and m=='cmp' and o=='ecx, edx' for a,m,o in r)
assert any(a==0x5da036 and m=='jg' for a,m,o in r)
time=json.loads((root/'public/assets/maps/E30.json').read_text('utf8'));survival=json.loads((root/'public/assets/maps/C30.json').read_text('utf8'));town=json.loads((root/'public/assets/maps/J00.json').read_text('utf8'));npc=next(n for n in town['npcs'] if n['name']=='极限老者')
assert len(time['spawns'])==57 and not survival['spawns']
start=npc['script'].split('#sub AA')[0];assert '#button 时间挑战' in start and '#button 生存挑战' not in start
rules={'fps':50,'time':{'map':'E30','entry':[15,25],'enemies':57,'name':'时间挑战'},'survival':{'map':'C30','entry':[49,53],'enemies':0,'name':'生存挑战','entryExposed':False}}
result={'passed':True,'sourceSha256':hashlib.sha256(n.data).hexdigest(),'evidenceFiles':files,'rules':rules,'fields':{'active':'global63ede0 (-1/0)','kind':'global63ede2 (survival0/time1)','frames':'global63ede4','survivalBest':'hero dword2058 (maximum)','timeBest':'hero dword205c (minimum nonzero)'},'npc':{'map':'J00','name':npc['name'],'position':[npc['x'],npc['y']],'scriptSha256':hashlib.sha256(npc['script'].encode()).hexdigest()},'maps':[{'id':m['id'],'sourceSha256':m['sourceSha256'],'spawnSha256':hashlib.sha256(json.dumps(m['spawns'],ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),'spawnCount':len(m['spawns'])} for m in [time,survival]],'texts':{key:n.string(addr) for key,addr in {'timeActive':0x41473c,'timeComplete':0x40fe78,'timeFailed':0x414778,'timeDuration':0x414768,'timeProgress':0x414758,'survivalActive':0x414700,'survivalEnded':0x40fe94,'survivalDuration':0x414728,'noRecord':0x40fa98}.items()},'nativeBehavior':['Commands reset frame count and transfer to the source arena; no entry fee or added reward.','The timer increments one engine frame; formatter truncates frames/50 and divides seconds by60.','Time success requires hero HP>0 and total native monster pool minus friends <=0; dead enemies leave the pool via native5c9313..5c9324.','Time failure on hero death does not update fastest time; success keeps minimum nonzero frames. Survival death keeps maximum frames.','Challenge-active death bypasses ordinary boss refresh reduction. Equipment randomizer5fcc20..5fd7f0 has no reads of challenge best-record fields.','Survival AA/A2 remains dormant in shipped NPC START. C30 has no spawn records or script-generated enemies.'], 'adaptations':['Portrait HUD and result/record panel reuse native HUD slices; manual exit does not claim a completed time record or living survival record.','Reuse existing source death strips (monster1.2s/hero1s) before treating enemies/player as released for results; all arena enemies are one-shot and do not use ordinary 20-second respawn.','Per-character Web active encounter snapshot preserves timer and each original spawn/converted ally rather than restoring a full arena on reload. Actor actions, in-flight projectiles and temporary zones restart as in ordinary combat saves.','Challenge arenas are omitted from generic unlocked-map travel; entry requires the native NPC command or a matching saved checkpoint. Invalid legacy arena saves fall back to the initial village home.', 'Live return goes back to the entry map/position; dead return uses the source-backed remembered town and original home point (see native-town-revival-source.json). Original desktop result/exit controls are adapted to the portrait flow.'],'survivalHasPlayableNativeEncounter':False,'fullNativeCombatEquivalent':False}
(root/'reports/native-challenge-source.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
print({'passed':True,'timeEnemies':57,'survivalEnemies':0,'survivalEntryExposed':False})
